import{_ as e,o as a,c,a2 as d}from"./chunks/framework.Bg-Zxr5O.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Controlling-Macro-Expansion.md","filePath":"manual-zh/Controlling-Macro-Expansion.md","lastUpdated":1785684581000}'),n={name:"manual-zh/Controlling-Macro-Expansion.md"};function r(t,o,E,s,p,l){return a(),c("div",null,[...o[0]||(o[0]=[d('<h4 id="_14-2-5-控制宏展开" tabindex="-1">14.2.5 控制宏展开 <a class="header-anchor" href="#_14-2-5-控制宏展开" aria-label="Permalink to &quot;14.2.5 控制宏展开&quot;">​</a></h4><p>多种因素控制着在不同情形下是否展开宏调用。在最高层级，<code>SET MEXPAND</code> 控制是否展开宏调用。默认情况下它是启用的。详见 <a href="./SET#SET-MEXPAND">SET MEXPAND</a>。</p><p>宏体可包含宏调用。默认情况下，这些会被展开。如果宏体包含 <code>!OFFEXPAND</code> 或 <code>!ONEXPAND</code> 指令，则 <code>!OFFEXPAND</code> 会禁用宏调用的展开，直到后续出现 <code>!ONEXPAND</code> 为止。</p><p>宏参数的值可包含宏调用。这些宏调用会被展开，除非该参数是用 <code>!NOEXPAND</code> 关键字声明的。</p><p>宏函数的参数是一种特殊上下文，不会展开宏调用。例如，若 <code>!vars</code> 是一个宏的名称，则 <code>!LENGTH(!vars)</code> 展开为 5；如果位置参数 1 的值为 <code>!vars</code>，则 <code>!LENGTH(!1)</code> 同样展开为 5。要在这些情况下展开宏，可使用 <code>!EVAL</code> 宏函数，例如 <code>!LENGTH(!EVAL(!vars))</code> 或 <code>!LENGTH(!EVAL(!1))</code>。详见 <a href="./Macro-Functions">宏函数</a>。</p><p>这些规则适用于宏调用，而不适用于宏体内对宏函数、宏参数以及由 <code>!DO</code> 或 <code>!LET</code> 创建的宏变量的使用，后者总是会被展开。</p><p><code>SET MEXPAND</code> 可以出现在宏体内部，但它不会影响其所在宏的展开。请改用 <code>!OFFEXPAND</code> 和 <code>!ONEXPAND</code>。</p>',7)])])}const N=e(n,[["render",r]]);export{_ as __pageData,N as default};
